import type { SdgnMissionQcm } from "./sdgnMissionQcmBank";

/** Banque officielle du DS SDGN Première (100 QCM). */
export const SDGN_DS_PREMIERE_QCM: SdgnMissionQcm[] = [
  { id: "sdgn-p-ds-01", chapter: 1, difficulte: "difficile", question: "Le dirigeant d'une association sportive décide de distribuer un excédent de trésorerie aux membres fondateurs. Pourquoi est-ce impossible ?", choix: ["Parce que le but d'une association est de produire un service non marchand, rendant la recherche de profit illégale.", "Parce qu'une association a une finalité non lucrative, ce qui lui interdit statutairement de partager ses excédents entre ses membres.", "Parce que la valeur ajoutée générée doit obligatoirement être réinvestie dans le bilan social de l'organisation.", "Parce que la structure de propriété d'une association appartient à l'État, seul bénéficiaire des dividendes."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-02", chapter: 1, difficulte: "difficile", question: "Lors d'un entretien, un collaborateur se met systématiquement sur la défensive. À quel concept correspond cette réaction ?", choix: ["À son attitude, car c'est une composante stable et innée de l'individu face aux normes de l'organisation.", "À son attitude, car il s'agit d'une prédisposition acquise (cognitive et affective) à réagir d'une certaine manière face à une situation.", "À sa personnalité, car elle reflète une évaluation momentanée de son environnement de travail.", "À sa personnalité, car elle traduit une émotion passagère liée au stress de l'évaluation hiérarchique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-03", chapter: 1, difficulte: "difficile", question: "Un salarié perçoit un salaire brut de 2 000 €. Les cotisations patronales sont de 800 € et les cotisations salariales de 400 €. Comment se calcule le coût global du travail ?", choix: ["Il est de 1 600 €, car le coût pour l'organisation se limite au salaire net versé après déductions.", "Il est de 2 400 €, car l'organisation supporte le salaire brut déduit des cotisations salariales, plus les charges patronales.", "Il est de 2 800 €, car le coût global intègre la rémunération brute contractuelle additionnée aux cotisations patronales.", "Il est de 3 200 €, car l'employeur provisionne le salaire brut, les charges patronales et réintègre les charges salariales."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-04", chapter: 1, difficulte: "difficile", question: "Le service informatique emploie un jargon technique qui exclut les commerciaux des débats. Comment analyser ce phénomène ?", choix: ["C'est une norme formelle, car elle valide hiérarchiquement la séparation des rôles dans l'organigramme.", "C'est un code culturel, car il renforce l'identité du groupe tout en créant une barrière informelle avec l'extérieur.", "C'est un stéréotype, car il stigmatise d'emblée le manque de compétences techniques des commerciaux.", "C'est un rituel d'entreprise, car il est répété à chaque réunion pour évaluer la productivité."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-05", chapter: 1, difficulte: "difficile", question: "Pour pallier des pics saisonniers, l'entreprise remplace l'embauche en CDI par des contrats de freelances. Quel est l'objectif RH précis ?", choix: ["Optimiser la flexibilité fonctionnelle pour adapter les qualifications aux ruptures technologiques.", "Obtenir une flexibilité quantitative externe afin d'ajuster strictement le coût du travail au volume d'activité.", "Accroître l'externalisation de l'activité pour renforcer l'intégration de la culture d'entreprise.", "Réduire le turn-over structurel en limitant l'engagement juridique des collaborateurs."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-06", chapter: 1, difficulte: "difficile", question: "Un employé critique sa direction sur son compte Twitter personnel \"ouvert\". Quel enjeu de gestion est ici soulevé ?", choix: ["Le respect de l'identité numérique, car l'employé engage l'e-réputation de l'entreprise et brouille la limite entre espaces privé et professionnel.", "La protection des données à caractère personnel, l'employé ayant utilisé le réseau social d'entreprise (RSE) sans consentement.", "L'application de la théorie des attentes, l'employé cherchant à modifier son statut par une influence paradoxale.", "La gestion des conflits par évitement, l'employé préférant le canal numérique au recours hiérarchique."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-07", chapter: 1, difficulte: "difficile", question: "Un supermarché automatise ses caisses et réaffecte les caissières au conseil client. Quelle est l'évolution RH ?", choix: ["Un élargissement des tâches, car les caissières effectuent des opérations plus nombreuses mais de même nature.", "Une modification de la qualification, l'automatisation exigeant de nouvelles compétences relationnelles et modifiant le profil attendu.", "Une baisse de la productivité du travail, le temps passé par client étant désormais supérieur à celui passé en caisse.", "Un ajustement mutuel des salaires en fonction de l'évolution des outils de gestion intégrée."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-08", chapter: 1, difficulte: "difficile", question: "Dans un cabinet, les associés déjeunent ensemble le vendredi et se tutoient. Que représentent ces pratiques ?", choix: ["Des rituels informels, qui participent à la culture de l'organisation en soudant le groupe d'appartenance.", "Des codes formels, imposés par le règlement pour standardiser les comportements individuels.", "Des normes hiérarchiques, instituant une relation d'autorité entre les différents niveaux de qualification.", "Des stéréotypes sociaux, permettant d'exclure les profils atypiques lors du recrutement."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-09", chapter: 1, difficulte: "difficile", question: "Face à une équipe peu impliquée, le manager décide de fixer les objectifs annuels via des ateliers de co-décision. Quel style de direction (Likert) est appliqué ?", choix: ["Le style consultatif, car le manager sollicite l'avis du groupe avant de centraliser la prise de décision finale.", "Le style participatif, car il décentralise le pouvoir de décision en impliquant directement le groupe dans la définition des buts.", "Le style paternaliste, car il utilise la réunion comme un outil de gratification sociale pour obtenir l'obéissance.", "Le style démocratique, car la fiche de poste de chaque salarié est redéfinie par un vote à la majorité."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-10", chapter: 1, difficulte: "difficile", question: "Une usine compte 100 ouvriers ayant produit 5 000 pièces. Le mois suivant, avec le même effectif, 6 000 pièces sont produites. Que s'est-il passé ?", choix: ["Les conditions de travail se sont améliorées, générant automatiquement une hausse de la rentabilité financière.", "La productivité du travail a augmenté, car le ratio \"quantité produite / moyens humains mobilisés\" est en hausse.", "La valeur ajoutée a augmenté, l'entreprise ayant réduit le coût de ses consommations intermédiaires.", "L'efficience s'est dégradée, car l'organisation a dû solliciter ses machines plus intensivement."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-11", chapter: 1, difficulte: "difficile", question: "Un recruteur écarte un profil en affirmant : \"Les jeunes de cette génération ne veulent pas s'investir\". À quel mécanisme cognitif recourt-il ?", choix: ["À une attribution causale externe, justifiant l'échec d'un candidat par la conjoncture économique.", "À un stéréotype, appliquant une croyance réductrice et généralisatrice à un groupe, ce qui génère une discrimination.", "À la culture de l'organisation, qui privilégie historiquement l'expérience à l'innovation.", "À l'influence minoritaire, le recruteur cherchant à imposer une nouvelle norme comportementale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-12", chapter: 1, difficulte: "difficile", question: "Les actionnaires exigent la baisse des charges pour augmenter les dividendes, tandis que les salariés réclament des primes. Il s'agit :", choix: ["D'un conflit d'intérêts interne, traduisant la difficulté d'équilibrer la répartition de la valeur entre les acteurs.", "D'une divergence culturelle, démontrant l'absence de rituels d'intégration communs.", "D'un conflit relationnel, lié à l'incompatibilité des personnalités entre dirigeants et représentants syndicaux.", "D'une asymétrie d'information, les actionnaires ignorant la réalité de l'activité de travail."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-13", chapter: 1, difficulte: "difficile", question: "Quel document formalise officiellement le rôle, le statut et les compétences exigées d'un individu au sein de l'action collective ?", choix: ["Le bilan social.", "La fiche de poste.", "Le tableau de bord RH.", "Le profil de recrutement."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-14", chapter: 1, difficulte: "difficile", question: "Le manager obtient l'adhésion de son équipe à un projet risqué sans recourir à la menace ni aux primes. Il mobilise :", choix: ["Le pouvoir légal de l'autorité, fondé sur sa position dans l'organigramme.", "Son leadership, c'est-à-dire sa capacité d'influence informelle et charismatique reconnue par le groupe.", "L'ajustement mutuel, en adaptant ses directives en temps réel face aux réactions de l'équipe.", "L'influence paradoxale, en obtenant l'accord de l'équipe par la manipulation des données."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-15", chapter: 1, difficulte: "difficile", question: "Pour fidéliser ses experts, une start-up octroie des actions gratuites et permet le télétravail. Ce sont des :", choix: ["Incitations, visant à motiver l'acteur et rétribuer sa contribution au-delà de la stricte obligation contractuelle.", "Indicateurs de performance sociale, inscrits obligatoirement au bilan de l'organisation.", "Variables d'hygiène, qui, selon Herzberg, suffisent à créer une motivation intrinsèque durable.", "Mécanismes de supervision, assurant le contrôle à distance de l'activité."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-16", chapter: 1, difficulte: "difficile", question: "Un groupe d'infirmières signe une pétition transmise à la direction de l'hôpital pour dénoncer le manque de lits. Cet acte relève :", choix: ["D'une e-communication descendante.", "D'une communication de groupe visant à argumenter et exercer une influence sur les décideurs.", "D'une communication interpersonnelle destinée à résoudre un conflit par évitement.", "D'une démarche d'intelligence collective en Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-17", chapter: 1, difficulte: "difficile", question: "Un salarié s'approprie systématiquement les idées de ses collègues lors des réunions de service. Il cherche ainsi à accroître :", choix: ["Sa qualification technique sur le projet.", "Son statut, c'est-à-dire la position sociale formelle et informelle qu'il occupe au sein du groupe.", "L'efficacité de la standardisation des procédés.", "L'efficience globale de son groupe de référence."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-18", chapter: 1, difficulte: "difficile", question: "La direction d'un centre d'appels suit quotidiennement la \"Durée Moyenne de Traitement\" des appels par opérateur. Il s'agit d'un indicateur mesurant :", choix: ["La rentabilité financière.", "La valeur perçue par le client.", "L'activité et la productivité du travail humain.", "Le bilan social de l'organisation."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-19", chapter: 1, difficulte: "difficile", question: "Lors d'un conflit agressif avec un client, l'employé reformule calmement le problème sans céder à la colère. Il mobilise sa compétence de :", choix: ["Négociation distributive.", "Contrôle de soi, indispensable pour gérer ses émotions et désamorcer une situation de crise interpersonnelle.", "Influence affective, en culpabilisant l'interlocuteur.", "Standardisation de l'attitude."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-20", chapter: 1, difficulte: "difficile", question: "Une PME confie la maintenance de son parc informatique à une Entreprise de Services du Numérique (ESN) spécialisée. Cette décision stratégique est :", choix: ["Une internalisation, visant à sécuriser la propriété des données.", "Une externalisation, permettant de confier une activité support à un tiers pour flexibiliser ses coûts.", "Une démarche de GPEC, pour adapter les compétences des informaticiens internes.", "Une modification de la structure de propriété, l'ESN devenant partenaire financier."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-21", chapter: 1, difficulte: "difficile", question: "Un taux de rotation (turn-over) de 40 % est constaté dans une usine. Quelle est l'analyse managériale correcte ?", choix: ["C'est un signe de flexibilité positive, réduisant la masse salariale fixe globale de l'entreprise.", "C'est un indicateur d'alerte sociale, traduisant un mauvais climat de travail et générant des coûts cachés de recrutement élevés.", "C'est la preuve que l'élargissement des tâches a atteint son objectif de productivité maximale.", "C'est le résultat inévitable de l'application de la théorie des facteurs moteurs d'Herzberg."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-22", chapter: 1, difficulte: "difficile", question: "Au sein du département R&D, l'ingénieur en chef valide seul toutes les décisions techniques sans consulter l'équipe. Il exerce :", choix: ["Une influence minoritaire.", "Une relation d'autorité formelle, imposant ses choix grâce au pouvoir conféré par sa position hiérarchique.", "Un leadership transformationnel, en imposant sa vision par le charisme.", "Un mécanisme d'ajustement mutuel, en centralisant les flux d'informations."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-23", chapter: 1, difficulte: "difficile", question: "Lors d'une réunion, un chef de produit démontre la viabilité d'un projet en projetant des tableaux de retour sur investissement chiffrés. Son influence repose sur :", choix: ["L'appel aux émotions et à la dynamique de groupe.", "L'argumentation rationnelle, utilisant la logique et la preuve pour convaincre l'auditoire.", "L'identité numérique, en manipulant des mégadonnées.", "L'effet de groupe de référence."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-24", chapter: 1, difficulte: "difficile", question: "Le \"groupe des anciens\" d'une entreprise se réunit tous les vendredis soirs en dehors des locaux. Il s'agit d'un :", choix: ["Groupe de travail formel, institué par la direction pour préserver la mémoire de l'entreprise.", "Groupe informel, constitué sur la base d'affinités et de normes partagées échappant à l'organigramme.", "Réseau social d'entreprise, destiné à organiser la e-communication externe.", "Comité d'experts en charge de la supervision directe."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-25", chapter: 2, difficulte: "difficile", question: "La GPEC (Gestion Prévisionnelle des Emplois et des Compétences) permet à la direction de :", choix: ["Licencier le personnel de manière discrétionnaire en cas de baisse de rentabilité.", "Anticiper les évolutions économiques et technologiques pour adapter la formation et le recrutement aux besoins futurs.", "Rédiger de façon unilatérale le règlement intérieur et les fiches de poste.", "Calculer le coût du travail journalier par unité de production."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-26", chapter: 2, difficulte: "difficile", question: "Un capteur logistique enregistre le code \"7845\" à l'entrée d'un entrepôt. À ce stade, ce code est :", choix: ["Une information, car il déclenche une décision de rangement.", "Une donnée, c'est-à-dire un élément brut non contextualisé, dépourvu de signification immédiate.", "Une connaissance, car il a été produit par un système informatique automatisé.", "Une intelligence collective, car il sera partagé sur le réseau."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-27", chapter: 2, difficulte: "difficile", question: "Lorsqu'un logiciel relie le code \"7845\" au produit \"Téléviseur X\" et au statut \"En rupture de stock\", on obtient :", choix: ["Une donnée à caractère personnel.", "Une information, la donnée initiale ayant été traitée, contextualisée et dotée de sens pour l'acteur.", "Une automatisation de tâche logistique.", "Une base de données en Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-28", chapter: 2, difficulte: "difficile", question: "Un site marchand conserve les adresses IP et l'historique d'achat nominatif de ses clients. Ce traitement relève :", choix: ["De l'Open Data, le site devant les mettre à disposition de ses partenaires.", "Des données à caractère personnel, strictement encadrées par le RGPD (consentement, finalité, sécurité).", "D'un PGI (Progiciel de Gestion Intégré) dont la fonction est de maximiser la transparence algorithmique.", "De l'intelligence collective, la communauté alimentant librement la base."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-29", chapter: 2, difficulte: "difficile", question: "La SNCF donne libre accès aux horaires en temps réel de ses trains via une interface de programmation (API). Cette démarche illustre :", choix: ["La centralisation du système d'information.", "L'Open Data (données ouvertes), favorisant la création de services à valeur ajoutée par des tiers indépendants.", "La faille sécuritaire du Cloud Computing.", "La création d'un réseau social d'entreprise (RSE) grand public."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-30", chapter: 2, difficulte: "difficile", question: "Une enseigne croise la géolocalisation de ses clients, la météo et ses stocks en temps réel pour envoyer des offres promotionnelles ultra-ciblées. Elle exploite :", choix: ["Les Mégadonnées (Big Data), transformant des volumes massifs d'informations hétérogènes en avantage stratégique et prédictif.", "L'automatisation des tâches industrielles de production.", "Les données à caractère personnel dans l'anonymat le plus strict.", "Un workflow de validation hiérarchique."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-31", chapter: 2, difficulte: "difficile", question: "Lorsqu'une vente est validée en caisse, le stock diminue, la commande fournisseur s'ajuste et le compte de résultat se met à jour simultanément. Ce système est :", choix: ["Un PGI (Progiciel de Gestion Intégré), qui garantit l'unicité de l'information via une base de données centralisée et décloisonne les processus.", "Un Cloud hybride, qui stocke les informations de manière redondante sur plusieurs serveurs isolés.", "Une application métier sectorielle, réservée exclusivement au département des ventes.", "Un mécanisme de supervision directe algorithmique."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-32", chapter: 2, difficulte: "difficile", question: "L'entreprise \"InnovTech\" décide d'héberger ses logiciels de création et ses données sur les serveurs distants d'Amazon (AWS). Ce choix technologique est :", choix: ["Le Crowdsourcing.", "L'informatique en nuage (Cloud Computing), qui apporte flexibilité et mobilité, mais soulève des risques de dépendance et de confidentialité.", "La Blockchain, garantissant la décentralisation absolue des fichiers.", "L'Open Data, ouvrant l'accès des serveurs aux autres startups du secteur."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-33", chapter: 2, difficulte: "difficile", question: "Un processus de gestion dans une organisation est défini comme :", choix: ["L'algorithme mathématique calculant le seuil de rentabilité.", "L'enchaînement structuré d'activités logiques, mobilisant différents acteurs et ressources pour atteindre un objectif précis.", "Le règlement intérieur dictant le comportement formel des salariés.", "La base de données stockant l'historique des clients."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-34", chapter: 2, difficulte: "difficile", question: "Le déploiement d'un outil de travail collaboratif en ligne (type Teams) dans une grande entreprise modifie la gestion en :", choix: ["Interdisant le travail en situation de mobilité.", "Favorisant les échanges transversaux et l'émergence de l'intelligence collective en cassant les silos hiérarchiques.", "Augmentant la rétention d'information au profit des cadres dirigeants.", "Automatisant la prise de décision stratégique sans intervention humaine."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-35", chapter: 2, difficulte: "difficile", question: "Un cabinet comptable utilise une IA pour numériser, classer et imputer automatiquement les factures fournisseurs. Quel est l'effet organisationnel ?", choix: ["La rigidité absolue, le comptable ne pouvant plus consulter les factures.", "L'automatisation de la tâche libère l'acteur du travail routinier, modifie son rôle vers l'analyse et accélère le processus de gestion.", "L'IA transforme les données financières en Open Data public.", "Le système supprime toute notion d'efficience financière."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-36", chapter: 2, difficulte: "difficile", question: "Le rôle premier d'un Système d'Information (SI) est de :", choix: ["Remplacer les ressources humaines par des systèmes experts.", "Collecter, stocker, traiter et diffuser l'information pertinente pour coordonner les actions et éclairer la prise de décision.", "Mesurer exclusivement le climat social via des enquêtes en ligne.", "Assurer la publicité des produits sur les réseaux sociaux."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-37", chapter: 2, difficulte: "difficile", question: "Pour améliorer l'ergonomie de son logiciel, une PME invite ses milliers d'utilisateurs à remonter les bugs et à proposer des lignes de code correctives sur un forum dédié. Elle mobilise :", choix: ["Un système de gestion intégrée (PGI).", "L'intelligence collective d'une communauté en ligne (crowdsourcing), la coopération générant une valeur supérieure aux experts isolés.", "La Blockchain, pour rémunérer les contributeurs en cryptomonnaies.", "L'informatique en nuage, pour héberger le code source."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-38", chapter: 2, difficulte: "difficile", question: "La direction des systèmes d'information attribue des profils d'accès différenciés : un vendeur ne peut pas consulter les salaires du personnel. Cela justifie que l'information est :", choix: ["Une ressource dont l'accessibilité doit être paramétrée selon les rôles pour garantir la sécurité et la confidentialité.", "Un élément obsolète dans un environnement de Big Data public.", "Totalement ouverte dans le cadre d'une politique d'e-communication interne.", "Protégée par l'asymétrie d'information commerciale."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-39", chapter: 2, difficulte: "difficile", question: "Une boutique physique lance son application de \"Click and Collect\". Pour l'organisation, cette intégration numérique génère :", choix: ["De la rigidité, en complexifiant le processus logistique traditionnel.", "De l'agilité organisationnelle, en développant un nouveau canal de distribution qui s'adapte aux usages connectés des clients.", "Une baisse inévitable de la marge commerciale unitaire.", "L'obligation légale d'automatiser entièrement ses entrepôts."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-40", chapter: 2, difficulte: "difficile", question: "Le circuit de validation d'un congé (demande du salarié -> notification au manager -> validation -> mise à jour RH) est géré automatiquement par le logiciel. Il s'agit d'un :", choix: ["Mégadonné (Big Data) comportemental.", "Flux de travail (Workflow), qui fiabilise, trace et fluidifie l'enchaînement des étapes du processus.", "Espace numérique de travail public.", "Algorithme de machine learning."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-41", chapter: 2, difficulte: "difficile", question: "La \"Transformation numérique\" d'une entreprise implique :", choix: ["Le remplacement de son parc informatique tous les 3 ans.", "Une mutation globale de ses processus, de son organisation du travail et de sa relation client par l'intégration systémique des technologies digitales.", "La cessation de toute activité physique au profit du télétravail exclusif.", "Le passage d'un modèle économique lucratif à un modèle Freemium."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-42", chapter: 2, difficulte: "difficile", question: "L'encyclopédie Wikipédia illustre le paradigme de l'intelligence collective parce que :", choix: ["Son code source est hébergé sur le cloud d'Amazon.", "La collaboration asynchrone d'une communauté d'anonymes permet d'élaborer une connaissance fiable supérieure à celle d'une équipe réduite d'experts.", "Elle utilise une Intelligence Artificielle pour rédiger automatiquement les articles.", "Elle revend les mégadonnées de ses lecteurs en Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-43", chapter: 2, difficulte: "difficile", question: "Le vol des bases de données clients d'une entreprise suite à un piratage engage sa responsabilité légale au titre :", choix: ["De la transparence algorithmique.", "Du manquement à la sécurisation des données à caractère personnel (RGPD), exposant l'entreprise à des sanctions et à la destruction de son e-réputation.", "Du principe de l'Open Data involontaire.", "De la défaillance du Workflow commercial."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-44", chapter: 2, difficulte: "difficile", question: "L'outil \"Intranet\" est principalement conçu pour :", choix: ["Prospecter de nouveaux clients à l'international.", "Diffuser des informations sécurisées et offrir un espace de collaboration réservé aux seuls membres de l'organisation (e-communication interne).", "Concurrencer les réseaux sociaux grand public comme Facebook.", "Stocker les sauvegardes du bilan comptable annuel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-45", chapter: 2, difficulte: "difficile", question: "Un progiciel (PGI) impose aux commerciaux de remplir 12 champs obligatoires avant de valider une remise, ce qu'ils faisaient avant oralement. Quel effet du SI observe-t-on ?", choix: ["Une flexibilité accrue de la force de vente.", "Une rigidité organisationnelle, le système informatisé contraignant les acteurs à respecter des procédures strictes limitant leur marge de manœuvre.", "Un ajustement mutuel facilité avec la comptabilité.", "La création de données ouvertes."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-46", chapter: 2, difficulte: "difficile", question: "Un fabricant de moteurs d'avion inclut des capteurs (IoT) transmettant des données en vol pour prévoir l'usure des pièces. Cette technologie permet :", choix: ["D'alimenter un réseau social d'entreprise.", "De créer un service de maintenance prédictive à forte valeur ajoutée grâce à la collecte continue d'informations opérationnelles.", "D'automatiser le pilotage de l'avion.", "De revendre les plans du moteur en Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-47", chapter: 2, difficulte: "difficile", question: "L'application Waze repose sur les alertes de trafic envoyées en temps réel par les conducteurs eux-mêmes. Le fonctionnement de l'application est donc basé sur :", choix: ["L'Open Data gouvernemental.", "L'intelligence collective, la communauté des usagers étant à la fois productrice et consommatrice de l'information optimisant le système.", "La Blockchain, pour rémunérer chaque signalement.", "Un système PGI de transport logistique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-48", chapter: 2, difficulte: "difficile", question: "Autoriser les salariés à travailler depuis leur smartphone personnel (BYOD) a pour effet de :", choix: ["Réduire les risques de cybersécurité grâce au cloisonnement matériel.", "Favoriser la mobilité et la réactivité, tout en posant un défi critique de sécurisation des accès au système d'information de l'entreprise.", "Baisser le coût global du travail, le salaire étant amputé du coût du téléphone.", "Transformer les données internes en données à caractère personnel publiques."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-49", chapter: 2, difficulte: "difficile", question: "Quel est l'inconvénient potentiel de l'hyper-automatisation d'un processus de décision de crédit bancaire par un algorithme ?", choix: ["L'augmentation drastique du temps de traitement des dossiers.", "La perte d'agilité face aux cas atypiques non prévus par la programmation, générant une rigidité face à l'usager.", "La suppression du RGPD pour les banques en ligne.", "La diminution des mégadonnées stockées."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-50", chapter: 3, difficulte: "difficile", question: "La e-communication d'une organisation concerne :", choix: ["Exclusivement la gestion des bad buzz sur les réseaux sociaux.", "La numérisation globale de ses flux d'informations, intégrant les canaux web, mobiles, intranets et les médias sociaux, en interne comme en externe.", "Le transfert robotisé de marchandises entre deux entrepôts.", "La publication annuelle obligatoire de son bilan financier."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-51", chapter: 3, difficulte: "difficile", question: "Une entreprise vend pour 100 000 € de marchandises. Elle a acheté 30 000 € de matières premières et payé 40 000 € de salaires. À combien s'élève sa Valeur Ajoutée (VA) ?", choix: ["30 000 €, calculée en déduisant toutes les charges (y compris les salaires) du chiffre d'affaires.", "70 000 €, calculée en déduisant uniquement les consommations intermédiaires (provenant des tiers) du chiffre d'affaires.", "100 000 €, la valeur ajoutée équivalant toujours à la production vendue.", "130 000 €, en additionnant le chiffre d'affaires et les achats."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-52", chapter: 3, difficulte: "difficile", question: "Dans le mécanisme de répartition de la Valeur Ajoutée, l'autofinancement correspond à la part :", choix: ["Reversée aux banques sous forme d'intérêts.", "Conservée par l'organisation (mise en réserve) pour assurer son développement futur et ses investissements.", "Distribuée aux actionnaires sous forme de dividendes.", "Payée à l'État sous forme d'impôts sur les bénéfices."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-53", chapter: 3, difficulte: "difficile", question: "L'action d'une entreprise pharmaceutique perd 30 % de sa cotation à l'annonce de l'échec d'un essai clinique. Quelle valeur est directement détruite ?", choix: ["La valeur partenariale, les fournisseurs refusant de livrer.", "La valeur financière boursière (actionnariale), qui reflète les anticipations de rentabilité du marché financier.", "La valeur sociale, le bilan social devant obligatoirement acter des licenciements.", "La valeur perçue, les clients boycottant la marque."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-54", chapter: 3, difficulte: "difficile", question: "Une marque de smartphone fixe son prix à 1 200 € pour un coût de production de 300 €. Les clients valident ce prix en raison du design, du prestige et du logiciel exclusif. Cette marge élevée est justifiée par :", choix: ["La valeur perçue, c'est-à-dire l'évaluation subjective par le client des bénéfices apportés par la marque (notoriété, image) justifiant un tel positionnement.", "La valeur boursière, chaque client devenant actionnaire à l'achat du produit.", "La réduction du coût global du travail en Asie de l'Est.", "L'optimisation algorithmique du seuil de rentabilité unitaire."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-55", chapter: 3, difficulte: "difficile", question: "Dans une organisation, évaluer l'efficience d'un processus consiste à :", choix: ["Vérifier si l'objectif final a été atteint, quel qu'en soit le prix.", "Mesurer l'optimisation des moyens (coûts, temps) mobilisés pour atteindre l'objectif fixé.", "Calculer le taux d'imposition sur le chiffre d'affaires.", "Augmenter la rentabilité commerciale en supprimant les contrôles qualité."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-56", chapter: 3, difficulte: "difficile", question: "Un service public avait pour objectif de traiter 10 000 dossiers avec un budget de 50 000 €. Il a traité les 10 000 dossiers mais en dépensant 80 000 €. Quelle est l'analyse de sa performance ?", choix: ["Le service est efficace (objectif atteint) mais inefficient (dépassement des ressources allouées).", "Le service est efficient (objectif atteint) mais inefficace (budget non respecté).", "Le service a maximisé sa rentabilité financière au détriment de la valeur sociale.", "Le service a subi une rupture technologique justifiant le coût."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-57", chapter: 3, difficulte: "difficile", question: "Le chiffre d'affaires, la part de marché et le taux de fidélisation sont des indicateurs permettant d'évaluer :", choix: ["La performance environnementale de l'entreprise.", "La performance commerciale, reflétant la dynamique de l'entreprise sur son marché cible.", "La valeur actionnariale à court terme.", "La qualité du dialogue social interne."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-58", chapter: 3, difficulte: "difficile", question: "L'association \"Croix-Rouge\" mène ses campagnes d'urgence grâce aux dons. Comment qualifier sa performance principale ?", choix: ["Elle est mesurée par sa rentabilité financière et la distribution de dividendes aux donateurs.", "Elle est mesurée par l'atteinte de ses buts non lucratifs (valeur et performance sociales) sous la contrainte d'un équilibre budgétaire.", "Elle est nulle, la performance étant un concept exclusivement réservé au secteur marchand privé.", "Elle se calcule en soustrayant ses impôts de son chiffre d'affaires."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-59", chapter: 3, difficulte: "difficile", question: "La profitabilité d'une entreprise se différencie de sa rentabilité car elle mesure :", choix: ["Le bénéfice généré par rapport aux capitaux propres investis.", "Le bénéfice (résultat net) rapporté au chiffre d'affaires, indiquant la marge nette de l'activité.", "Le chiffre d'affaires rapporté au nombre de salariés.", "La valeur boursière divisée par les dettes de l'entreprise."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-60", chapter: 3, difficulte: "difficile", question: "Un restaurateur obtient de nombreuses recommandations élogieuses et une note de 4.8/5 sur une plateforme d'avis communautaires. Il a consolidé :", choix: ["Sa valeur financière à très court terme.", "Sa valeur perçue (e-réputation), ce qui aura un impact mécanique positif sur sa performance commerciale future.", "Sa performance sociale, en réduisant l'absentéisme de ses cuisiniers.", "Sa valeur partenariale envers ses fournisseurs de matières premières."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-61", chapter: 3, difficulte: "difficile", question: "Si le prix de vente d'un bien reste stable sur le marché, mais que l'entreprise subit une forte hausse de ses charges (électricité, salaires), l'impact direct est :", choix: ["Une amélioration de la valeur perçue par l'usager.", "Un effet de ciseau réduisant inévitablement sa marge et sa rentabilité, l'entreprise absorbant l'inflation des coûts.", "Une augmentation automatique de l'efficience de ses machines.", "Une hausse de la part de la valeur ajoutée destinée aux actionnaires."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-62", chapter: 3, difficulte: "difficile", question: "Un tableau de bord de gestion est pertinent pour un dirigeant si :", choix: ["Il contient l'intégralité des milliers de données comptables brutes de l'année.", "Il regroupe un nombre limité d'indicateurs clés (financiers et non financiers) actualisés pour alerter et guider les décisions stratégiques.", "Il est publié en Open Data à l'attention des concurrents.", "Il mesure exclusivement l'empreinte carbone de la flotte automobile."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-63", chapter: 3, difficulte: "difficile", question: "Une entreprise industrielle supprime un composant bon marché mais toxique par un substitut écologique plus cher, amputant son bénéfice net de 15 %. Ce choix illustre :", choix: ["L'échec du modèle économique Freemium.", "La recherche d'une performance environnementale assumée, démontrant que les différentes dimensions de la performance globale peuvent être contradictoires à court terme.", "La volonté de maximiser la rentabilité financière des actionnaires au mépris de l'éthique.", "L'inefficacité du bilan fonctionnel pour la prise de risque."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-64", chapter: 3, difficulte: "difficile", question: "Les actionnaires votent pour s'octroyer 90 % des bénéfices en dividendes. Les salariés font grève pour exiger que cette somme finance une hausse générale des salaires. Que révèle cette tension ?", choix: ["La convergence naturelle des buts dans les entreprises à but lucratif.", "Le caractère potentiellement conflictuel de la création de valeur, l'entreprise devant arbitrer la répartition de la richesse (Valeur Ajoutée) entre des attentes d'acteurs divergentes.", "L'impossibilité de mesurer la valeur financière de manière objective.", "La primauté absolue du bilan social sur le compte de résultat."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-65", chapter: 3, difficulte: "difficile", question: "Quel document l'entreprise (de plus de 300 salariés) doit-elle fournir pour synthétiser des indicateurs tels que l'emploi, les rémunérations, et les conditions de travail ?", choix: ["Le rapport RSE environnemental.", "Le Bilan Social, outil d'information et de concertation mesurant la performance sociale.", "Le tableau de financement des immobilisations.", "Le registre de l'Open Data salarial."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-66", chapter: 3, difficulte: "difficile", question: "Un grand constructeur coopère depuis 10 ans avec le même équipementier pour développer des moteurs hybrides, partageant les risques et les brevets. Ils développent ainsi :", choix: ["La rentabilité actionnariale de court terme.", "La valeur partenariale, fondée sur la confiance, la stabilité des relations et la co-création de richesse avec un acteur externe stratégique.", "Une stratégie de prix d'écrémage sur le marché local.", "Une rupture technologique liée aux Mégadonnées."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-67", chapter: 3, difficulte: "difficile", question: "Un réseau de bus municipal (gratuit pour les usagers) affiche des bus toujours pleins et très appréciés. Cependant, la mairie s'endette lourdement chaque année pour payer l'entretien et l'essence. L'analyse révèle que le service est :", choix: ["Totalement inefficace et inefficient.", "Efficace (haute valeur perçue, objectif de mobilité atteint) mais confronté à une inefficience financière (dérive des coûts de fonctionnement).", "Créateur d'une forte valeur boursière pour la municipalité.", "Doté d'un modèle économique en \"Bait and Hook\" très rentable."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-68", chapter: 3, difficulte: "difficile", question: "Une entreprise achète un téléphone 300 € à son usine et le revend 800 € en boutique. L'écart de 500 € représente :", choix: ["La taxe sur la valeur ajoutée (TVA) perçue par l'État.", "La marge commerciale brute, qui devra ensuite couvrir les charges de distribution (salaires des vendeurs, loyer de la boutique) avant de dégager un bénéfice.", "Le résultat net final qui sera distribué intégralement aux actionnaires.", "La valeur partenariale de la marque de téléphone."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-69", chapter: 3, difficulte: "difficile", question: "La \"Performance Globale\" d'une organisation contemporaine implique qu'elle soit évaluée sur :", choix: ["Sa seule capacité à minimiser le coût de son personnel au niveau mondial.", "L'équilibre qu'elle parvient à instaurer entre ses performances économiques, sociales (RH) et environnementales (sociétales).", "Sa vitesse à délocaliser ses unités de production polluantes.", "Son taux d'endettement à court terme (Trésorerie passive)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-70", chapter: 3, difficulte: "difficile", question: "Une entreprise de e-commerce multiplie son chiffre d'affaires par deux, mais ses bénéfices s'effondrent. Quelle contrainte l'explique logiquement ?", choix: ["Une fidélisation trop forte de sa clientèle.", "Une explosion de ses charges opérationnelles (coûts logistiques, publicité, matières) supérieure à la croissance de ses revenus, écrasant sa profitabilité.", "L'émission de nouvelles actions gratuites en bourse.", "L'amélioration spectaculaire de l'efficience de ses préparateurs de commandes."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-71", chapter: 3, difficulte: "difficile", question: "Une application mobile obtient une note de 1.5/5 sur les stores, les utilisateurs se plaignant de bugs incessants. L'impact direct pour l'éditeur est :", choix: ["L'amélioration de son bilan social interne.", "Une destruction de sa valeur perçue, entraînant une fuite de l'audience et l'effondrement de sa performance commerciale future.", "L'augmentation de son seuil de rentabilité unitaire.", "L'obligation légale d'adopter un modèle Freemium."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-72", chapter: 3, difficulte: "difficile", question: "Lors de la répartition de la Valeur Ajoutée, l'entreprise doit obligatoirement honorer certaines parts avant toute décision. Laquelle relève d'une contrainte fiscale ?", choix: ["Le paiement des intérêts aux banques privées.", "Le paiement des impôts et taxes à l'État et aux collectivités.", "La distribution de dividendes aux actionnaires majoritaires.", "La mise en réserves (autofinancement) pour la R&D."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-73", chapter: 3, difficulte: "difficile", question: "Une marque de vêtements de luxe brûle ses invendus pour éviter qu'ils ne soient soldés. À court terme, elle préserve l'exclusivité (valeur perçue). À moyen terme, cette pratique l'expose à :", choix: ["L'augmentation exponentielle de sa valeur partenariale en Asie.", "Un scandale éthique et une forte dégradation de sa performance environnementale, menaçant son image de marque auprès des nouvelles générations.", "La requalification juridique de ses contrats de travail.", "Une hausse de sa productivité marginale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-74", chapter: 3, difficulte: "difficile", question: "Un analyste consulte le Compte de Résultat de l'entreprise pour connaître :", choix: ["La liste détaillée du patrimoine (bâtiments, dettes bancaires) possédé à la date de clôture.", "La dynamique de formation du bénéfice ou de la perte sur l'année, en comparant l'ensemble des produits (ventes) à l'ensemble des charges (dépenses).", "L'empreinte carbone liée à la fabrication de ses produits phares.", "L'indice d'égalité hommes-femmes au sein de la direction."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-75", chapter: 4, difficulte: "difficile", question: "La performance d'une administration publique (ex: France Travail) se jauge par des indicateurs qualitatifs et quantitatifs spécifiques, car :", choix: ["Elle n'est soumise à aucune contrainte de budget.", "Sa finalité n'est pas la rentabilité financière, mais la satisfaction de l'usager et l'efficience dans l'utilisation des fonds publics pour remplir sa mission de service public.", "Elle reverse l'intégralité de sa valeur ajoutée sous forme de dividendes citoyens.", "Elle opère sur un marché fortement concurrentiel gouverné par la loi de l'offre et de la demande."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-76", chapter: 4, difficulte: "difficile", question: "L'activité de \"ChocoPâques\" est concentrée sur deux mois dans l'année. Cette contrainte sectorielle exige du gestionnaire qu'il intègre fortement la notion de :", choix: ["Délocalisation technologique.", "Saisonnalité, imposant d'anticiper le besoin en trésorerie pour couvrir les mois de faible activité (découpage du temps).", "Seuil de rentabilité journalier.", "Biais d'apprentissage algorithmique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-77", chapter: 4, difficulte: "difficile", question: "La mise en place d'une \"Veille informationnelle\" proactive permet au dirigeant de :", choix: ["Surveiller le temps de pause de ses salariés via des badges connectés.", "Collecter et analyser des informations sur son environnement (lois, innovations, concurrents) afin de réduire l'incertitude liée à l'avenir et prendre des décisions éclairées.", "Calculer instantanément le coût du travail.", "Contourner les obligations du RGPD sur les données personnelles."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-78", chapter: 4, difficulte: "difficile", question: "La démarche budgétaire d'une entreprise (prévision des ventes et dépenses de l'année à venir) s'appuie sur :", choix: ["L'analyse exclusive du Bilan de l'année précédente.", "Des données prospectives et de la simulation, permettant d'anticiper les ressources nécessaires et les déficits de trésorerie potentiels.", "La valeur environnementale des actifs immatériels.", "La certitude absolue qu'aucun risque externe ne surviendra."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-79", chapter: 4, difficulte: "difficile", question: "L'entreprise \"InnovJouet\" supporte 100 000 € de charges fixes. Elle vend son jouet 50 € avec une charge variable de 30 € par unité. Son seuil de rentabilité est atteint à :", choix: ["2 000 unités, car il faut diviser les charges fixes (100k) par le prix de vente (50).", "5 000 unités, car la marge sur coût variable (50-30 = 20€) doit couvrir les charges fixes (100 000 / 20 = 5 000), point où l'entreprise ne réalise ni perte ni bénéfice.", "10 000 unités, seuil défini par le ministère de l'industrie pour les PME.", "3 333 unités, en divisant les charges fixes par les charges variables."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-80", chapter: 4, difficulte: "difficile", question: "L'interdiction prochaine des véhicules thermiques en ville est, pour les constructeurs traditionnels, un facteur de risque :", choix: ["Interne, lié à l'aptitude de leurs dirigeants à prendre des risques démesurés.", "Externe, d'ordre réglementaire et technologique, pouvant précipiter l'obsolescence de leur gamme et nécessitant une mutation industrielle lourde.", "Interne, lié à une mauvaise gestion de la pyramide des âges (GPEC).", "Climatique, lié à une catastrophe naturelle sur les lignes de montage."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-81", chapter: 4, difficulte: "difficile", question: "Un manager décide de lancer un parfum très onéreux sans tester le marché, par intuition. Le produit échoue totalement. L'origine de ce risque est :", choix: ["Un facteur interne, lié à une décision de gestion irrationnelle et au profil de risque du décideur ignorant les outils prospectifs.", "Un aléa externe lié à une asymétrie d'information des fournisseurs.", "Une rupture technologique des réseaux sociaux.", "Le délai d'actualisation de l'information boursière."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-82", chapter: 4, difficulte: "difficile", question: "Une agence marketing base sa campagne \"Jeunesse\" sur une étude des réseaux sociaux datant de 2017. Elle s'expose à un échec retentissant car elle a oublié que la valeur de l'information dépend de :", choix: ["Sa gratuité (Open Data).", "Son actualité : une information n'a de pertinence décisionnelle que si elle est pérenne ou régulièrement mise à jour face aux mutations rapides de la demande.", "Son origine interne ou externe.", "Son interopérabilité algorithmique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-83", chapter: 4, difficulte: "difficile", question: "Plus l'horizon prévisionnel de l'organisation est lointain (long terme), plus :", choix: ["La prise de décision est standardisée par les algorithmes.", "Le niveau d'incertitude et de risque est élevé, l'environnement (concurrentiel, technologique, légal) étant soumis à des mutations difficiles à anticiper.", "Les charges fixes se transforment mécaniquement en charges variables.", "La rentabilité boursière est mathématiquement garantie."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-84", chapter: 4, difficulte: "difficile", question: "Une usine européenne dépend exclusivement d'un fournisseur taïwanais pour ses composants électroniques. Une grève des ports asiatiques bloque les expéditions. Le risque matérialisé est :", choix: ["Une obsolescence programmée interne.", "Une dépendance d'approvisionnement (risque externe logistique), paralysant la capacité de production de l'organisation.", "Une asymétrie d'information délibérée.", "Un effet de levier financier négatif (effet de massue)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-85", chapter: 4, difficulte: "difficile", question: "Un chef de chantier utilise un calendrier prévisionnel (diagramme de Gantt) pour planifier l'intervention des maçons, électriciens et peintres. Cet outil de gestion du temps sert à :", choix: ["Évaluer la performance environnementale du béton.", "Coordonner l'interdépendance des tâches, simuler les délais de mise en œuvre et éviter les goulots d'étranglement pénalisant le délai final.", "Modifier la structure de propriété de l'entreprise de BTP.", "Calculer le coût du travail journalier selon les conventions collectives."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-86", chapter: 4, difficulte: "difficile", question: "Le service commercial d'une PME sait que le client phare va annuler sa commande, mais cache l'information à la production pour ne pas perdre sa prime. L'usine continue de fabriquer à perte. C'est un problème lié à :", choix: ["La rupture technologique des machines.", "L'asymétrie et la rétention d'information en interne, entraînant des décisions de gestion désastreuses.", "L'obsolescence naturelle du cycle de vie du produit.", "L'impact de la taxe carbone sur les stocks."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-87", chapter: 4, difficulte: "difficile", question: "Le \"Cycle de vie\" d'un produit démontre que lors de la phase de \"Déclin\", l'organisation fait face au risque :", choix: ["De ne plus pouvoir satisfaire une demande en hyper-croissance.", "D'obsolescence de son produit face aux nouvelles attentes ou technologies, l'obligeant à l'abandonner ou à innover en urgence pour maintenir ses parts de marché.", "D'atteindre son seuil de rentabilité trop précocement.", "D'une amélioration trop rapide de la rentabilité financière."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-88", chapter: 4, difficulte: "difficile", question: "En finance, le principe d'actualisation repose sur l'idée \"qu'un euro reçu aujourd'hui a plus de valeur qu'un euro reçu dans 10 ans\". Cela traduit :", choix: ["Que la monnaie matérielle s'use physiquement avec le temps.", "Le lien direct entre le temps et la valeur financière : une somme disponible aujourd'hui peut être placée et générer des intérêts, compensant le risque et le temps d'immobilisation.", "Le fait que l'inflation est une donnée ouverte (Open Data).", "Que l'entreprise ne doit payer ses fournisseurs qu'au comptant."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-89", chapter: 4, difficulte: "difficile", question: "Un PDG décide de refuser le passage au commerce en ligne, convaincu que ce n'est qu'une mode passagère, menant son entreprise à la faillite 3 ans plus tard. Ce risque résulte de :", choix: ["L'obsolescence des matières premières.", "L'aptitude du dirigeant (facteur interne), incapable d'anticiper le marché ou refusant de sortir de sa \"zone de confort\", ce qui a figé la stratégie de l'organisation.", "La réglementation stricte du RGPD.", "La durée légale du travail."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-90", chapter: 4, difficulte: "difficile", question: "Une entreprise de transport dépend à 100 % du gazole. Une crise géopolitique fait doubler le prix du baril en un mois. Quelle est l'incidence sur la gestion ?", choix: ["Un risque externe de dépendance énergétique qui fait exploser les coûts (charges variables) et détruit la marge bénéficiaire si l'entreprise ne peut pas répercuter la hausse sur ses prix.", "Une amélioration inattendue de l'EBE (Excédent Brut d'Exploitation) grâce à la déduction des taxes pétrolières.", "Un renouvellement automatique du parc par des véhicules électriques financé par le Cloud.", "Une baisse du Besoin en Fonds de Roulement (BFR)."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-91", chapter: 4, difficulte: "difficile", question: "Un contrôleur de gestion utilise les fonctions de \"simulation\" d'un tableur (Excel) avant de fixer le prix d'un produit. Cet outil permet :", choix: ["D'annuler complètement le risque de faillite.", "De tester plusieurs scénarios (\"Que se passe-t-il si les ventes baissent de 15 % ?\") pour anticiper l'incidence de différents risques sur le résultat et sécuriser la décision.", "De transformer les données financières à caractère personnel en données ouvertes (Open Data).", "D'empêcher les concurrents d'analyser le marché (asymétrie)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-92", chapter: 4, difficulte: "difficile", question: "L'usine d'un fabricant de puces électroniques est inondée, arrêtant la production durant un mois. Quelle est la conséquence économique directe (incidence du risque) ?", choix: ["Aucune, car les charges fixes s'annulent automatiquement lorsque l'usine est fermée.", "Une double perte : l'effondrement du chiffre d'affaires (impossibilité de livrer) et le maintien des charges fixes (salaires, loyers, amortissements), creusant lourdement le déficit.", "L'augmentation du Fonds de Roulement Net Global, les assurances payant l'intégralité des stocks.", "Une baisse du seuil de rentabilité proportionnelle aux jours de fermeture."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-93", chapter: 4, difficulte: "difficile", question: "La marque de \"Fast Fashion\" Shein produit massivement des vêtements jetables expédiés par avion, avec une forte empreinte carbone. Quel risque principal pèse sur ce modèle à moyen terme ?", choix: ["L'allongement du cycle de vie des produits, qui réduira la fréquence d'achat.", "Un risque d'ordre sociétal et réglementaire, l'évolution de la demande vers l'éco-responsabilité et d'éventuelles \"taxes carbone\" pouvant pénaliser lourdement sa performance.", "La sur-actualisation de son système d'information de gestion (PGI).", "La suppression de la théorie des parties prenantes en Asie."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-94", chapter: 4, difficulte: "difficile", question: "La prospective (long terme) se distingue de la prévision budgétaire (court/moyen terme) par :", choix: ["Le type d'organisation concernée : la prospective est réservée à l'État.", "La nature de la réflexion : le budget gère les équilibres financiers chiffrés sur un an, la prospective imagine des scénarios stratégiques face aux incertitudes lourdes de l'avenir lointain (ex: impact de l'IA en 2035).", "L'obligation légale de la publier au registre du commerce.", "L'utilisation exclusive de l'ajustement mutuel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-95", chapter: 4, difficulte: "difficile", question: "Face au risque d'impayés de la part de ses clients B2B, l'entreprise souscrit un contrat auprès d'une société d'assurance-crédit. La méthode de gestion des risques employée est :", choix: ["L'acceptation totale du risque, l'entreprise provisionnant elle-même ses pertes.", "Le transfert du risque à un tiers, moyennant le paiement d'une prime, pour sécuriser sa trésorerie et limiter l'incidence financière des aléas.", "L'évitement du risque, l'entreprise refusant de vendre à crédit.", "La réduction du risque à la source par l'innovation de procédé."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-96", chapter: 4, difficulte: "difficile", question: "L'entreprise \"CuisinePlus\" réalise une enquête quantitative pour tester l'attrait d'un nouveau design auprès d'un panel avant de lancer la fabrication. Cet outil prospectif vise à :", choix: ["Capter les données à caractère personnel pour les revendre en Open Data.", "Réduire l'incertitude liée à l'acceptation par le marché et limiter le risque d'échec commercial lourd en capital.", "Homogénéiser les méthodes de calcul des coûts complets en usine.", "Modifier le mode de contrôle imposé par les dirigeants."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-97", chapter: 4, difficulte: "difficile", question: "Une PME technologique a une rentabilité fragile mais décide d'investir 50 % de son chiffre d'affaires en R&D sur une technologie non encore prouvée. Elle illustre :", choix: ["Le principe d'obsolescence programmée des ressources humaines.", "Une très forte aptitude au risque de sa direction, pariant sur une rupture technologique majeure qui peut soit la ruiner, soit lui conférer un avantage concurrentiel décisif.", "Le rejet de l'informatique en nuage (Cloud).", "Le calcul du seuil de rentabilité inversé."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-98", chapter: 4, difficulte: "difficile", question: "Lors de la conception du \"TGV M\", le retard de livraison du nouveau système de freinage par le sous-traitant A empêche le montage des rames par les équipes B. Ce risque de délai met en évidence :", choix: ["La gestion du temps complexe due aux phénomènes de contingence et à la forte interdépendance des acteurs dans la chaîne logistique et de production.", "L'asymétrie d'information entre le ministère des Transports et les usagers.", "L'efficience absolue de la structure organisationnelle de l'entreprise.", "Le principe de démocratie participative appliqué à l'ingénierie."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-99", chapter: 4, difficulte: "difficile", question: "Une chaîne de jouets constitue des stocks massifs de patinettes électriques prévoyant qu'elles seront \"le\" cadeau de Noël. En décembre, la mode est passée aux drones. L'incidence du risque pour l'organisation est :", choix: ["Un aléa climatique majeur.", "Une erreur d'anticipation temporelle immobilisant durablement des ressources financières dans un stock invendable, pesant sur le BFR et la rentabilité (ventes à perte obligatoires).", "Un risque externe lié à la dépendance technologique envers les fabricants de puces.", "La réduction de son empreinte environnementale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-100", chapter: 4, difficulte: "difficile", question: "En synthèse, l'enseignement de Sciences de Gestion et Numérique (SDGN) démontre que la gestion d'une organisation :", choix: ["Est une science exacte où les algorithmes permettent d'éliminer totalement le facteur temps et l'incertitude liée aux comportements humains.", "Consiste à prendre des décisions dans un environnement complexe, en arbitrant en permanence entre la création de valeur (performance globale), la prise de risque assumée et l'intégration des mutations technologiques et sociétales.", "Se résume à appliquer la théorie de l'agence pour maximiser la rentabilité boursière à très court terme.", "Exige la standardisation stricte de toutes les qualifications pour supprimer les interactions informelles."] as [string, string, string, string], bonIndex: 1 },
];
